{
  "critique": [
    {
      "design": "r1A",
      "good": "The version strings and audit columns are easy to scan, and all headers fit on one line. The long package identifier wraps across three lines while remaining visually tied to its row.",
      "problems": "The advisory URL splits within its long token, making it harder to follow. The notes and package columns both create three-line cells, but in different rows.",
      "cause": "Notes is 296px wide, leaving 275px for text—5px less than its longest unbreakable content."
    },
    {
      "design": "r1B",
      "good": "The wider Notes column avoids the reported mid-word split. License and vulnerability values remain compact and align well for vertical comparison.",
      "problems": "The pre-release version wraps onto a second line, interrupting the package–version identification pair. The long package identifier still needs three lines.",
      "cause": "Version is reduced to 110px, leaving 89px for text, while Notes receives 308px."
    },
    {
      "design": "r1C",
      "good": "The full pre-release version stays on one line, the headers remain intact, and the status columns are easy to compare.",
      "problems": "The long package identifier breaks at a less natural point, separating a hyphen from the preceding segment. That makes the identifier harder to read even though the table height is unchanged.",
      "cause": "Package is 182px wide, leaving 161px for text—5px less than its longest unbreakable segment. Notes has the 301px needed for its longest segment."
    }
  ],
  "done": false,
  "designs": [
    {
      "name": "balanced-version",
      "widths": [187, 117, 106, 135, 301],
      "change": "Give Package and Notes their stated minimum widths for unbreakable content, taking 5px from Version. Test whether the pre-release version can remain readable at this intermediate width."
    },
    {
      "name": "compact-license",
      "widths": [187, 122, 101, 135, 301],
      "change": "Preserve the full Version width and the stated minimums for Package and Notes by taking 5px from License. Test whether Proprietary wraps or splits, and whether that trade-off is preferable to a wrapped version."
    }
  ]
}
